def max_subarray_length_k(nums: list[int], k: int) -> int:
    # Check if empty
    if len(nums) == 0 or k > len(nums):
        return 0

    max_val = -float('inf')
    # Loop through all possible subarrays
    for i in range(len(nums) - k + 1):
        sub_sum = sum(nums[i:i+k])
        if sub_sum > max_val:
            max_val = sub_sum

    return int(max_val) if max_val != -float('inf') else 0
